<script setup lang="ts">
import { ref, computed, onMounted, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useSession } from '../../app/session'
import { api, mediaUrl } from '../../api/client'
import type { User, Page, Card } from '../../api/types'
import NoteCard from '../../components/NoteCard.vue'
import ErrorBanner from '../../components/ErrorBanner.vue'
import RequireLogin from '../../components/RequireLogin.vue'
const route = useRoute(); const session = useSession(); const own = computed(() => route.path === '/me'); const profile = ref<User | null>(null); const cards = ref<Card[]>([]); const error = ref(''); const busy = ref(false); const editing = ref(false); const bio = ref(''); const nickname = ref('')
const following = ref<User[]>([]); const followers = ref<User[]>([])
async function load() { if (own.value && !session.user) return; error.value = ''; try { profile.value = await api<User>(own.value ? '/me' : '/users/' + route.params.id); nickname.value = profile.value.nickname; bio.value = profile.value.bio; cards.value = (await api<Page<Card>>('/search?authorId=' + profile.value.id)).items; const lists = await Promise.all([api<Page<User>>('/users/' + profile.value.id + '/following'), api<Page<User>>('/users/' + profile.value.id + '/followers')]); following.value = lists[0].items; followers.value = lists[1].items } catch (e) { error.value = e instanceof Error ? e.message : '加载失败' } }
async function save() { busy.value = true; try { profile.value = await api<User>('/me/profile', { method: 'PUT', body: { nickname: nickname.value, bio: bio.value, avatarMediaId: profile.value?.avatarMediaId ?? null } }); session.user = profile.value; editing.value = false; session.notify('资料已更新') } catch (e) { error.value = e instanceof Error ? e.message : '保存失败' } finally { busy.value = false } }
async function avatar(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file || !profile.value) return; const body = new FormData(); body.append('file', file); body.append('purpose', 'AVATAR'); try { const uploaded = await api<{ id: string }>('/media', { method: 'POST', body }); profile.value.avatarMediaId = uploaded.id; await save() } catch (e) { error.value = e instanceof Error ? e.message : '上传失败' } }
watch(() => route.fullPath, load); onMounted(load)
</script>
<template><RequireLogin v-if="own && !session.user" /><div v-else><ErrorBanner :message="error" :retry="load" /><template v-if="profile"><header class="profile-header"><img v-if="profile.avatarMediaId" class="avatar large" :src="mediaUrl(profile.avatarMediaId)" alt="头像"><span v-else class="avatar large">{{ profile.nickname.slice(0, 1) }}</span><div><h1>{{ profile.nickname }}</h1><p>{{ profile.bio || '还没有简介，生活本身就是最好的介绍。' }}</p><p class="hint">{{ following.length }} 位关注 · {{ followers.length }} 位粉丝（本页）</p></div><button v-if="own" class="button" @click="editing = !editing">编辑资料</button></header><form v-if="editing && own" class="form-stack narrow section" @submit.prevent="save"><label class="field"><span>昵称</span><input v-model="nickname" maxlength="40" required></label><label class="field"><span>简介</span><textarea v-model="bio" maxlength="300" /></label><label class="field"><span>更新头像</span><input type="file" accept="image/jpeg,image/png,image/webp" @change="avatar"></label><button class="button primary" :disabled="busy">保存资料</button></form><nav class="tabs"><span class="active">公开笔记</span><RouterLink v-if="own" to="/creator">我的草稿与发布状态</RouterLink><RouterLink v-if="own" to="/preferences">兴趣设置</RouterLink></nav><div v-if="cards.length" class="waterfall"><NoteCard v-for="note in cards" :key="note.id" :note="note" /></div><div v-else class="empty-state"><h2>还没有公开笔记</h2><p>每段值得分享的生活，都可以从这里开始。</p></div><details class="section"><summary>关注与粉丝</summary><h3 class="small-heading">正在关注</h3><div class="action-group"><RouterLink v-for="person in following" :key="person.id" :to="'/users/' + person.id" class="button small">{{ person.nickname }}</RouterLink></div><h3 class="small-heading">粉丝</h3><div class="action-group"><RouterLink v-for="person in followers" :key="person.id" :to="'/users/' + person.id" class="button small">{{ person.nickname }}</RouterLink></div></details></template></div></template>
